-- PRP-001 (FRE0013 F061/F103), restrictive part — apply after the code that
-- writes courses through /api/courses is deployed.
--
-- 1. Courses are written only by the API (service role), which validates every
--    field. Clients keep read access: anyone reads active courses
--    (courses_public_read) and a tutor also reads their own inactive ones.
-- 2. Open times are computed now, so the free slots pre-generated by the old
--    model are withdrawn (cancelled, not deleted: old rows may be referenced).

drop policy if exists courses_tutor_manage on public.courses;
drop policy if exists courses_tutor_read_own on public.courses;
create policy courses_tutor_read_own
on public.courses
for select
to authenticated
using (auth.uid() = tutor_id);

revoke insert, update, delete, truncate on public.courses from anon, authenticated;

update public.lessons l
set status = 'cancelled', updated_at = now()
where l.status = 'available'
  and l.student_id is null
  and not exists (
    select 1 from public.bookings b
    where b.lesson_id = l.id and b.status in ('pending', 'confirmed')
  );
